import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Diagramme","description":"","frontmatter":{"title":"Diagramme","covers":{"screens":["SCR-067"],"stories":["US-074"]}},"headers":[],"relativePath":"de/usage/diagrams.md","filePath":"de/usage/diagrams.md"}`),a={name:`de/usage/diagrams.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="diagramme" tabindex="-1">Diagramme <a class="header-anchor" href="#diagramme" aria-label="Permalink to “Diagramme”">​</a></h1><p>Ein Diagramm modelliert einen Geschäftsprozess oder eine andere Sicht auf die Architektur mit der Notation eines <a href="./../administration/metamodel-editing#viewpoints">Viewpoints</a>, zum Beispiel <em>Process Model (BPMN 2.0)</em>. Diese Version von OEA verwaltet Diagramme als Objekte: Du legst sie an, findest, benennst um, löschst und stellst sie wieder her. Die Zeichenfläche, auf der du Elemente platzierst, folgt in einer späteren Version; bis dahin zeigt die Seite eines Diagramms seinen Namen, seine Beschreibung und seinen Viewpoint.</p><p>Zum Ansehen brauchst du die Berechtigung <code>entity:read</code> (zum Beispiel die Rolle <code>viewer</code>). Anlegen, Umbenennen und Löschen braucht <code>entity:write</code>, Wiederherstellen <code>entity:restore</code> (Rolle <code>enterprise-architect</code>). Service-Accounts mit <code>entity:write</code> können Diagramme über die API wie Personen anlegen und ändern.</p><h2 id="diagramme-finden" tabindex="-1">Diagramme finden <a class="header-anchor" href="#diagramme-finden" aria-label="Permalink to “Diagramme finden”">​</a></h2><p>Du findest Diagramme an drei Stellen:</p><ul><li><strong>Die Seite <em>Diagramme</em>:</strong> Wähle in der Kopfzeile <em>Diagramme</em>. Die Seite listet die Diagramme nach Namen, unabhängig von Gross- und Kleinschreibung, jeweils mit ihrem Viewpoint, der Notation des Viewpoints und dem Zeitpunkt der letzten Änderung. Gib einen Namensteil in <em>Nach Name filtern</em> ein, um die Liste einzugrenzen; Zeichen wie <code>%</code> und <code>_</code> gelten, wie eingegeben. Die Liste zeigt 50 Diagramme auf einmal; wähle <em>Mehr laden</em> für die nächsten. Ohne Diagramm meldet die Seite <em>Noch keine Diagramme.</em></li><li><strong>Der Browser:</strong> Die Kategorie <em>Diagramme</em> unter <em>Aktueller Stand</em> in der Seitenleiste listet die Diagramme mit der Notation als kleiner Markierung (siehe <a href="./navigation#browser">Navigationsbaum</a>).</li><li><strong>Der Navigationsbaum:</strong> Diagramme, die in einen Ordner eingeordnet wurden (siehe <a href="./navigation#place-a-diagram">Diagramm einordnen</a>).</li></ul><p>Wähle ein Diagramm, um seine Seite zu öffnen.</p><h2 id="diagramm-anlegen" tabindex="-1">Diagramm anlegen <a class="header-anchor" href="#diagramm-anlegen" aria-label="Permalink to “Diagramm anlegen”">​</a></h2><ol><li><p>Wähle auf der Seite <em>Diagramme</em> <em>Diagramm anlegen</em>.</p></li><li><p>Fülle den Dialog aus:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Name</td><td>erforderlich, 1 bis 200 Zeichen; eindeutig unter den Diagrammen, unabhängig von Gross- und Kleinschreibung; umgebende Leerzeichen werden entfernt</td></tr><tr><td>Beschreibung</td><td>optional, bis zu 2000 Zeichen</td></tr><tr><td>Viewpoint</td><td>erforderlich; der Viewpoint des Diagramms und seine Notation</td></tr></tbody></table></li><li><p>Wähle <em>Anlegen</em>. Das neue, leere Diagramm öffnet sich.</p></li></ol><p>Der Viewpoint wird beim Anlegen festgelegt und lässt sich später nicht ändern. Ist der Name vergeben, meldet der Dialog <em>Ein Diagramm mit diesem Namen gibt es schon.</em></p><h2 id="diagramm-umbenennen-und-loschen" tabindex="-1">Diagramm umbenennen und löschen <a class="header-anchor" href="#diagramm-umbenennen-und-loschen" aria-label="Permalink to “Diagramm umbenennen und löschen”">​</a></h2><p><em>Umbenennen</em> ändert Namen und Beschreibung eines Diagramms, auf der Seite <em>Diagramme</em> und auf der Seite des Diagramms. Hat jemand anderes das Diagramm inzwischen geändert, meldet der Dialog das; lade die Seite neu und wiederhole deine Änderung.</p><p><em>Löschen</em> fragt nach einer Bestätigung. Ein gelöschtes Diagramm erscheint nicht mehr in der Liste, im Browser und im Navigationsbaum, und sein Name kann wieder verwendet werden. <strong>Die Entitäten des Repositorys bleiben.</strong> Das Diagramm selbst lässt sich wiederherstellen (siehe unten).</p><h2 id="diagramm-wiederherstellen" tabindex="-1">Diagramm wiederherstellen <a class="header-anchor" href="#diagramm-wiederherstellen" aria-label="Permalink to “Diagramm wiederherstellen”">​</a></h2><p>Mit der Berechtigung <code>entity:restore</code> listet der Schalter <em>Gelöschte anzeigen</em> auf der Seite <em>Diagramme</em> die gelöschten Diagramme mit Zeitpunkt und Person des Löschens. Wähle <em>Wiederherstellen</em>, um ein Diagramm samt seinen Einträgen im Navigationsbaum zurückzuholen. Hat inzwischen ein anderes Diagramm seinen Namen bekommen, meldet die Seite das, und das Diagramm bleibt gelöscht; benenne zuerst das andere Diagramm um.</p><h2 id="viewpoint-loschen" tabindex="-1">Viewpoint löschen <a class="header-anchor" href="#viewpoint-loschen" aria-label="Permalink to “Viewpoint löschen”">​</a></h2><p>Diagramme können ohne ihren Viewpoint nicht bestehen. Löschst du einen Viewpoint, den Diagramme nutzen, werden sie mit ihm <strong>endgültig</strong> gelöscht, auch die bereits gelöschten; die Entitäten bleiben. Die Bestätigung nennt die Anzahl der Diagramme, die gelöscht werden (siehe <a href="./../administration/metamodel-editing#viewpoints">Viewpoints</a>). Dasselbe geschieht, wenn eine neue Version eines <a href="./../administration/metamodel-packages">Metamodell-Pakets</a> einen systemdefinierten Viewpoint nicht mehr enthält.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><p>Die Diagramme sind über <code>/diagrams</code> verfügbar (siehe die <a href="./../api/">API-Referenz</a>):</p><ul><li><code>GET /diagrams</code> listet die Diagramme nach Namen. <code>q</code> ist ein Namensteil (höchstens 200 Zeichen), <code>pageSize</code> ist 1 bis 200 (Standard 50), und <code>page</code> beginnt bei 0. Die Antwort enthält <code>nextCursor</code>; sende ihn als <code>cursor</code> zusammen mit <code>page</code> um 1 erhöht, um fortzufahren. Ein Cursor einer anderen Abfrage wird mit 400 abgelehnt, das <code>cursor</code> nennt.</li><li><code>POST /diagrams</code> legt ein Diagramm aus <code>name</code>, <code>description</code> und <code>viewpointId</code> an; <code>GET /diagrams/{id}</code> liest es; <code>PUT /diagrams/{id}</code> ändert <code>name</code> und <code>description</code> (eine <code>viewpointId</code> wird ignoriert); <code>DELETE /diagrams/{id}</code> löscht es. Jede Änderung braucht den Header <code>If-Match</code> mit der gelesenen Version (<code>&quot;3&quot;</code>); ohne ihn lautet die Antwort 428, mit einer anderen Version 412. Die Antworten tragen die neue Version als <code>ETag</code>.</li><li><code>GET /diagrams/deleted</code> listet die gelöschten Diagramme, und <code>POST /diagrams/{id}/restore</code> mit <code>If-Match</code> stellt eines wieder her; beides braucht <code>entity:restore</code>. Ein Diagramm, das nicht gelöscht ist, antwortet mit 409 (<code>urn:oea:problem:diagram-not-deleted</code>).</li><li>Ein vergebener Name antwortet mit 422 und dem Problemtyp <code>urn:oea:problem:diagram-name-taken</code>; sonstige ungültige Eingaben antworten mit 422 und nennen das Feld in <code>invalidFields</code> (<code>name</code>, <code>description</code> oder <code>viewpointId</code>). Ein unbekanntes oder gelöschtes Diagramm antwortet mit 404.</li><li>Jede Änderung steht im Audit-Trail als <code>diagram.created</code>, <code>diagram.updated</code>, <code>diagram.deleted</code> oder <code>diagram.restored</code>.</li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};